import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Data-Summarization.md","filePath":"manual-en/CTABLES-Data-Summarization.md","lastUpdated":1785684581000}'),o={name:"manual-en/CTABLES-Data-Summarization.md"};function n(i,t,s,l,m,h){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_15-7-2-data-summarization" tabindex="-1">15.7.2 Data Summarization <a class="header-anchor" href="#_15-7-2-data-summarization" aria-label="Permalink to &quot;15.7.2 Data Summarization&quot;">​</a></h4><p>The <code>CTABLES</code> command allows the user to control how the data are summarized with <em>summary specifications</em> , syntax that lists one or more summary function names, optionally separated by commas, and which are enclosed in square brackets following a variable name on the <code>TABLE</code> subcommand. When all the variables are categorical, summary specifications can be given for the innermost nested variables on any one axis. When a scalar variable is present, only the scalar variable may have summary specifications.</p><p>The following example includes a summary specification for column and row percentages for categorical variables, and mean and median for a scalar variable:</p><pre><code>CTABLES
    /TABLE=age [MEAN, MEDIAN] BY gender
    /TABLE=ageGroup [COLPCT, ROWPCT] BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Column %</th><th>Row %</th><th>Column %</th><th>Row %</th></tr></thead><tbody><tr><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Male</td><td>Female</td><td></td><td></td><td></td></tr><tr><td></td><td>Mean</td><td>Median</td><td>Mean</td><td>Median</td><td></td></tr><tr><td>D1. AGE: What is your age?</td><td>46</td><td>45</td><td>50</td><td>52</td><td></td></tr><tr><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>.0%</td><td>.</td><td>.0%</td><td>.</td></tr><tr><td>16 to 25</td><td>19.0%</td><td>54.0%</td><td>13.1%</td><td>46.0%</td><td></td></tr><tr><td>26 to 35</td><td>15.2%</td><td>49.2%</td><td>12.7%</td><td>50.8%</td><td></td></tr><tr><td>36 to 45</td><td>15.6%</td><td>47.2%</td><td>14.2%</td><td>52.8%</td><td></td></tr><tr><td>46 to 55</td><td>16.8%</td><td>44.8%</td><td>16.8%</td><td>55.2%</td><td></td></tr><tr><td>56 to 65</td><td>16.5%</td><td>41.4%</td><td>18.9%</td><td>58.6%</td><td></td></tr><tr><td>66 or older</td><td>17.0%</td><td>36.0%</td><td>24.4%</td><td>64.0%</td><td></td></tr></tbody></table><p>A summary specification may override the default label and format by appending a string or format specification or both (in that order) to the summary function name. For example:</p><pre><code>CTABLES /TABLE=ageGroup [COLPCT &#39;Gender %&#39; PCT5.0,
                         ROWPCT &#39;Age Group %&#39; PCT5.0]
               BY gender.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Gender %</th><th>Age Group %</th><th>Gender %</th><th>Age Group %</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>Male</td><td>Female</td><td></td><td></td></tr><tr><td>Age group</td><td>15 or younger</td><td>0%</td><td>.</td><td>0%</td><td>.</td></tr><tr><td>16 to 25</td><td>19%</td><td>54%</td><td>13%</td><td>46%</td><td></td></tr><tr><td>26 to 35</td><td>15%</td><td>49%</td><td>13%</td><td>51%</td><td></td></tr><tr><td>36 to 45</td><td>16%</td><td>47%</td><td>14%</td><td>53%</td><td></td></tr><tr><td>46 to 55</td><td>17%</td><td>45%</td><td>17%</td><td>55%</td><td></td></tr><tr><td>56 to 65</td><td>16%</td><td>41%</td><td>19%</td><td>59%</td><td></td></tr><tr><td>66 or older</td><td>17%</td><td>36%</td><td>24%</td><td>64%</td><td></td></tr></tbody></table><p>In addition to the standard formats, <code>CTABLES</code> allows the user to specify the following special formats:</p><table tabindex="0"><thead><tr><th>NEGPAREN w . d</th><th>Encloses negative numbers in parentheses.</th><th>42.96</th><th>(42.96)</th></tr></thead><tbody><tr><td>NEQUAL w . d</td><td>Adds a N= prefix.</td><td>N=42.96</td><td>N=-42.96</td></tr><tr><td>PAREN w . d</td><td>Encloses all numbers in parentheses.</td><td>(42.96)</td><td>(-42.96)</td></tr><tr><td>PCTPAREN w . d</td><td>Encloses all numbers in parentheses with a ‘ % ’ suffix.</td><td>(42.96%)</td><td>(-42.96%)</td></tr></tbody></table><p>Parentheses provide a shorthand to apply summary specifications to multiple variables. For example, both of these commands:</p><pre><code>CTABLES /TABLE=ageGroup[COLPCT] + membersOver16[COLPCT] BY gender.
CTABLES /TABLE=(ageGroup + membersOver16)[COLPCT] BY gender.
</code></pre><p>produce the same output shown below:</p><table tabindex="0"><thead><tr><th></th><th></th><th>Male</th><th>Female</th></tr></thead><tbody><tr><td></td><td></td><td>S3a. GENDER:</td><td></td></tr><tr><td></td><td></td><td>Column %</td><td>Column %</td></tr><tr><td>Age group</td><td>15 or younger</td><td>.0%</td><td>.0%</td></tr><tr><td>16 to 25</td><td>19.0%</td><td>13.1%</td><td></td></tr><tr><td>26 to 35</td><td>15.2%</td><td>12.7%</td><td></td></tr><tr><td>36 to 45</td><td>15.6%</td><td>14.2%</td><td></td></tr><tr><td>46 to 55</td><td>16.8%</td><td>16.8%</td><td></td></tr><tr><td>56 to 65</td><td>16.5%</td><td>18.9%</td><td></td></tr><tr><td>66 or older</td><td>17.0%</td><td>24.4%</td><td></td></tr><tr><td>S1. Including yourself, how many members of this household are age 16 or older?</td><td>None</td><td>.0%</td><td>.0%</td></tr><tr><td>1</td><td>21.4%</td><td>35.0%</td><td></td></tr><tr><td>2</td><td>61.9%</td><td>52.3%</td><td></td></tr><tr><td>3</td><td>11.0%</td><td>8.2%</td><td></td></tr><tr><td>4</td><td>4.2%</td><td>3.2%</td><td></td></tr><tr><td>5</td><td>1.1%</td><td>.9%</td><td></td></tr><tr><td>6 or more</td><td>.4%</td><td>.4%</td><td></td></tr></tbody></table><p>The following sections list the available summary functions. After each function’s name is given its default label and format. If no format is listed, then the default format is the print format for the variable being summarized.</p><table tabindex="0"><thead><tr><th>• Summary Functions for Individual Cells</th><th></th><th></th></tr></thead><tbody><tr><td>• Summary Functions for Groups of Cells</td><td></td><td></td></tr><tr><td>• Summary Functions for Adjusted Weights</td><td></td><td></td></tr><tr><td>• Unweighted Summary Functions</td><td></td><td></td></tr></tbody></table>`,16)])])}const p=d(o,[["render",n]]);export{c as __pageData,p as default};
